import type {UserId} from '../../../types'

import {useUserSelect} from './AllUsersSelect.hooks'
import UserSelect from './UserSelect'
import type {UserSelectSelectedItem} from './UserSelect.types'

type Props = {
  className?: string
  popupClassName?: string
  label?: string
  selected: UserId | string | null | undefined // userId or username
  withAllUsers?: boolean
  onChange: (selected: UserSelectSelectedItem) => unknown
}

function AllUserSelect({
  className,
  label,
  popupClassName,
  selected,
  withAllUsers = true,
  onChange,
}: Props) {
  const {data, selectedItems, loading} = useUserSelect({
    selected,
    withAllUsers,
  })

  return (
    <UserSelect
      className={className}
      data={data}
      label={label}
      popupClassName={popupClassName}
      selected={(selectedItems as UserSelectSelectedItem) || null}
      loading={loading}
      onChange={onChange}
    />
  )
}

export default AllUserSelect
