import {graphql} from 'react-relay'

export const allUserSelectQuery = graphql`
  query AllUserSelectQuery($skip: Boolean = false) {
    users @skip(if: $skip) {
      user {
        id
        avatars {
          urlToSize40
        }
        name
        username
      }
    }
  }
`

export const allUserSelectFragment = graphql`
  fragment AllUserSelectFragment on User {
    id
    avatars {
      urlToSize40
    }
    name
    username
  }
`
