import {useContext, useMemo} from 'react'
import {useLazyLoadQuery, useFragment} from 'react-relay'

import {CurrentUserKeyContext} from '../../../contexts/currentUserKey'
import {usePermission} from '../../../hooks/usePermission'
import {Permission, ROOT_PROJECT_ID, type UserId} from '../../../types'

import type {AllUserSelectFragment$key} from './__generated__/AllUserSelectFragment.graphql'
import type {AllUserSelectQuery} from './__generated__/AllUserSelectQuery.graphql'
import {allUserSelectFragment, allUserSelectQuery} from './AllUserSelect.queries'
import type {UserSelectData} from './UserSelect.types'
import {
  ALL_REGISTERED_USERS_LABEL,
  ALL_USERS_SELECT_ITEM,
  getSelectItem,
  getSelectedItemByUserId,
  sortUsersByName,
  getSelectedItem,
} from './UserSelect.utils'

type UseUserSelectProps = {
  withAllUsers?: boolean
  selected: string[] | UserId | string | null | undefined
}

export const useUserSelect = ({withAllUsers = true, selected}: UseUserSelectProps) => {
  const hasPermission = usePermission(Permission.VIEW_USER_PROFILE, ROOT_PROJECT_ID)

  const {users} = useLazyLoadQuery<AllUserSelectQuery>(allUserSelectQuery, {
    skip: !hasPermission,
  })

  const currentUserKey: AllUserSelectFragment$key | null = useContext(CurrentUserKeyContext)
  const currentUser = useFragment(allUserSelectFragment, currentUserKey)

  // Sort users by name
  const sortedUsers = useMemo(() => sortUsersByName(users), [users])

  // Calculate loading state
  const loading = currentUser == null || (hasPermission && users == null)

  // Generate the data for selection
  const data = useMemo(() => {
    let items: UserSelectData = withAllUsers ? [ALL_USERS_SELECT_ITEM] : []

    if (currentUser != null) {
      items.push(getSelectItem({user: currentUser, isCurrentUser: true}))
    }
    if (sortedUsers.length > 0) {
      items.push(ALL_REGISTERED_USERS_LABEL)
      items = items.concat(
        sortedUsers.filter(user => user.id !== currentUser?.id).map(user => getSelectItem({user})),
      )
    }
    return items
  }, [currentUser, sortedUsers, withAllUsers])

  const selectedItems = useMemo(() => {
    if (Array.isArray(selected)) {
      return selected.map(s => data.find(item => s === item.username)).filter(Boolean)
    }
    return selected != null && selected !== ''
      ? (getSelectedItemByUserId(data, selected) ?? getSelectedItem(data, selected as string))
      : null
  }, [data, selected])

  return {
    data,
    selectedItems,
    loading,
  }
}
